Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

#include <iostream>
#include <fstream>
#include <string>
#include <map>

int main() {
  // Open the text file
  std::ifstream file("text_file.txt");

  // Map for storing word counts
  std::map<std::string, int> word_count;

  // Read the file line by line
  std::string line;
  while (std::getline(file, line)) {
    // Tokenize the line
    std::istringstream iss(line);
    std::string word;
    while (iss >> word) {
      // Increment the word count if the word is in the map
      if (word_count.count(word) > 0) {
        word_count[word]++;
      } else {
        word_count[word] = 1;
      }

      // Increment the word count if the word matches the specified word
      if (word == "my_word") {
        ++word_count["my_word"];
      }
    }
  }

  // Print the word count
  std::cout << "Word: " << "my_word" << " Count: " << word_count["my_word"] << std::endl;

  return 0;
}

