    let mid = Math.floor((left + right) / 2);
    let midVal = arr[mid];

    if (midVal < target) {
      left = mid + 1;
    } else if (midVal > target) {
      right = mid - 1;
    } else {
      return mid;
    }
  }

  return -1;
}
